function clean(v, fallback) {
  return (typeof v === 'string' && v && !/^\{\{.*\}\}$/.test(v) && v) || fallback;
}
function cleanObj(v, fallback) {
  return (v && typeof v === 'object' && !Array.isArray(v) && v) || fallback;
}
return {
  url: input.url,
  method: clean(input.method, 'GET'),
  headers: cleanObj(input.headers, {}),
  body_json: cleanObj(input.body_json, {})
};

function getPath(obj, pathStr) {
  var cur = obj;
  String(pathStr).split('.').forEach(function(k) { cur = (cur || {})[k]; });
  return cur;
}
var fetchNode = (input && input.fetch) || {};
var fetchOk = fetchNode.success === true;
var rawBody = (fetchNode.data && typeof fetchNode.data.body === 'string' && fetchNode.data.body) || '';
var errText = (typeof fetchNode.error === 'string' && fetchNode.error) || '';
var parsedJson = null;
var jsonParseError = null;
try { parsedJson = JSON.parse(rawBody); } catch (e) { jsonParseError = String((e && e.message) || e); }
var checks = (Array.isArray(input.checks) && input.checks) || [];
var results = [];
checks.forEach(function(chk) {
  chk = chk || {};
  var mode = chk.mode || 'json_path';
  var negate = chk.negate === true;
  var haystack = (chk.source === 'error' && errText) || rawBody;
  var actual = null;
  var ok = false;
  switch (mode) {
    case 'contains': {
      actual = haystack.indexOf(String(chk.expected)) !== -1;
      ok = (negate && !actual) || (!negate && actual);
      break;
    }
    default: {
      actual = getPath(parsedJson, chk.path || '');
      ok = String(actual) === String(chk.expected);
      break;
    }
  }
  results.push({ label: (chk.label || chk.path) || String(chk.expected), mode: mode, source: chk.source || 'body', expected: chk.expected, actual: actual, ok: ok });
});
return {
  url: input.url,
  fetch_ok: fetchOk,
  fetch_error: errText || null,
  json_parse_error: jsonParseError,
  results: results,
  all_ok: results.every(function(r) { return r.ok; })
};
